<?php
namespace App\Services;
use App\Models\{InspeksiMobil,KendaraanPelanggan,PengajuanMobil};use Illuminate\Support\Facades\DB;use RuntimeException;
class PengajuanMobilService {
 private function code():string{do{$c='PJM-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));}while(PengajuanMobil::where('kode_pengajuan',$c)->exists());return $c;}
 public function create(int $customerId,int $vehicleId,string $expected,?string $note):PengajuanMobil{return DB::transaction(function()use($customerId,$vehicleId,$expected,$note){$v=KendaraanPelanggan::whereKey($vehicleId)->where('id_pelanggan',$customerId)->where('status','aktif')->first();if(!$v)throw new RuntimeException('Kendaraan bukan milik akun ini atau tidak aktif.');$p=new PengajuanMobil();$p->forceFill(['kode_pengajuan'=>$this->code(),'id_pelanggan'=>$customerId,'id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'merk'=>$v->merk,'model'=>$v->model,'tipe'=>$v->tipe,'tahun'=>$v->tahun,'warna'=>$v->warna,'transmisi'=>$v->transmisi,'bahan_bakar'=>$v->bahan_bakar,'nomor_polisi'=>$v->nomor_polisi,'nomor_rangka'=>$v->nomor_rangka,'nomor_mesin'=>$v->nomor_mesin,'kilometer'=>$v->kilometer,'harga_harapan'=>$expected,'catatan'=>$note,'status'=>'diajukan'])->save();return $p;});}
 public function process(int $id):void{DB::transaction(function()use($id){$p=PengajuanMobil::lockForUpdate()->findOrFail($id);if($p->status!=='diajukan')throw new RuntimeException('Pengajuan tidak berada pada status diajukan.');$p->forceFill(['status'=>'menunggu_inspeksi'])->save();});}
 public function startInspection(int $id,int $petugasId,int $km):InspeksiMobil{return DB::transaction(function()use($id,$petugasId,$km){$p=PengajuanMobil::lockForUpdate()->findOrFail($id);if($p->status!=='menunggu_inspeksi')throw new RuntimeException('Pengajuan belum siap diinspeksi.');$i=new InspeksiMobil();$i->forceFill(['id_pengajuan'=>$p->id_pengajuan,'id_petugas'=>$petugasId,'tanggal_inspeksi'=>now(),'kilometer'=>$km])->save();$p->forceFill(['status'=>'dalam_inspeksi'])->save();return $i;});}
 public function saveInspection(int $id,array $data,int $petugasId):InspeksiMobil{return DB::transaction(function()use($id,$data,$petugasId){$p=PengajuanMobil::lockForUpdate()->findOrFail($id);if(!in_array($p->status,['dalam_inspeksi','penawaran_diberikan'],true))throw new RuntimeException('Inspeksi tidak dapat diedit pada status ini.');$i=$p->inspeksi()->first();if(!$i)throw new RuntimeException('Inspeksi belum dibuat.');$i->forceFill($data+['id_petugas'=>$petugasId])->save();return $i;});}
 public function offer(int $id,string $price):void{DB::transaction(function()use($id,$price){$p=PengajuanMobil::lockForUpdate()->findOrFail($id);if(!in_array($p->status,['dalam_inspeksi','penawaran_diberikan'],true))throw new RuntimeException('Penawaran tidak dapat diubah pada status ini.');$i=$p->inspeksi()->first();if(!$i)throw new RuntimeException('Inspeksi belum dibuat.');$i->forceFill(['harga_penawaran'=>$price])->save();$p->forceFill(['status'=>'penawaran_diberikan'])->save();});}
 public function decision(int $id,int $customerId,string $decision):void{DB::transaction(function()use($id,$customerId,$decision){$p=PengajuanMobil::where('id_pelanggan',$customerId)->lockForUpdate()->findOrFail($id);if($p->status!=='penawaran_diberikan'||!in_array($decision,['disetujui','ditolak'],true))throw new RuntimeException('Keputusan penawaran tidak dapat dilakukan.');$p->forceFill(['status'=>$decision])->save();});}
}
